          "position": 1,
          "name": "Request a Free Quote",
          "text": "Call STS at 844-699-2913 or use the online quote form. Provide equipment types, approximate quantities, access conditions, and preferred timing.",
          "url": "https://www.stselectronicrecyclinginc.com/quote"
        },
        {
          "@type": "HowToStep",
          "position": 2,
          "name": "Schedule the Pickup",
          "text": "STS reviews the project scope and coordinates a pickup schedule for the Bakersfield location. Planning accounts for equipment volume, loading access, and organizational timing requirements."
        },
        {
          "@type": "HowToStep",
          "position": 3,
          "name": "Arrange Secure Transport",
          "text": "Equipment is collected in Bakersfield and moved through the STS processing network with documented handling and chain of custody information."
        },
        {
          "@type": "HowToStep",
          "position": 4,
          "name": "Track Assets and Handle Data",
          "text": "STS can record equipment details and apply the selected media-handling process. NIST SP 800-88 guidance may inform sanitization and physical destruction decisions."
        },
        {
          "@type": "HowToStep",
          "position": 5,
          "name": "Complete Environmental Processing",
          "text": "Equipment is directed toward documented reuse, material recovery, or recycling pathways based on condition, equipment type, and project requirements."
        },
        {
          "@type": "HowToStep",
          "position": 6,
          "name": "Receive Final Documentation",
          "text": "After the selected processing steps are completed, STS provides the applicable asset, handling, and disposition records for the Bakersfield project.",
          "url": "https://www.stselectronicrecyclinginc.com/certificate-of-destruction-services"
